inline Flags<MapBufferAccessMask> operator|(MapBufferAccessMask a, MapBufferAccessMask b) {
    return Flags<MapBufferAccessMask>(a) | Flags<MapBufferAccessMask>(b);
}
inline Flags<MapBufferAccessMask> operator&(MapBufferAccessMask a, MapBufferAccessMask b) {
    return Flags<MapBufferAccessMask>(a) & Flags<MapBufferAccessMask>(b);
}
inline Flags<MapBufferAccessMask> operator^(MapBufferAccessMask a, MapBufferAccessMask b) {
    return Flags<MapBufferAccessMask>(a) ^ Flags<MapBufferAccessMask>(b);
}
inline Flags<MapBufferAccessMask> operator~(MapBufferAccessMask a) {
    return ~Flags<MapBufferAccessMask>(a);
}

