// ── Extension runtime ────────────────────────────────────────────────────────
#ifndef GLAZE_GL_NO_EXTENSIONS

/**
 * @brief Lightweight token bound to a single OpenGL extension.
 *
 * Each `gl::exts::*` constant carries the extension's Khronos name and a
 * pointer to its corresponding C-side ``GLAZE_EXT_<name>`` flag, which is set
 * by ``glazeLoadExtensions``. The bool conversion returns whether the driver
 * exposed the extension at load time, so ``if (gl::exts::ARB_buffer_storage)``
 * is the idiomatic guard. Pair with ``gl::supports(...)`` for explicit calls.
 */
struct Extension {
    const char *name;
    const int  *loaded;
    explicit operator bool() const noexcept {
        return loaded != nullptr && *loaded != 0;
    }
};

namespace exts {
} // namespace exts

/** @brief Returns true if the driver exposes the extension at load time. */
inline bool supports(const Extension &ext) noexcept { return static_cast<bool>(ext); }
/** @brief Returns true if the driver exposes an extension by name (string fallback). */
inline bool supports(const char *name) { return ::glazeHasExtension(name) != 0; }
/** @brief Returns true if the bound GL context's version is at least major.minor. */
inline bool supports(int major, int minor) { return ::glazeIsVersionSupported(major, minor) != 0; }

#endif // GLAZE_GL_NO_EXTENSIONS

