/**
 * @brief Type-traits hook that associates an OpenGL handle type with the
 * functor types responsible for creating and destroying it. Specialized once
 * per resource handle below; the primary template is intentionally undefined
 * so misuse fails at compile time.
 */
template<typename H> struct HandleTraits;

